function validate([start, result]) {
  if (typeof start !== 'string' || typeof result !== 'string') return 'start and result must be strings.';
  if (start.length < 1 || start.length > 10000) return 'start needs 1 to 10000 characters.';
  if (result.length !== start.length) return 'start and result must have the same length.';
  if (!/^[LRX]+$/.test(start) || !/^[LRX]+$/.test(result)) return "Use only the characters 'L', 'R' and 'X'.";
  return null;
}

