function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(8000, 10000) : int(1, 8);
  const fill = rand() < 0.5 ? 0.5 : 0.2 + rand() * 0.6;
  const start = Array.from({ length: n }, () => (rand() < fill ? 'X' : rand() < 0.5 ? 'L' : 'R'));
  const mode = rand();
  if (size === 'small' && mode < 0.25) {
    // An unrelated string of the same length.
    return [start.join(''), Array.from({ length: n }, () => 'LRX'[int(0, 2)]).join('')];
  }
  // Build a reachable result: each L moves left and each R moves right, keeping their order.
  const pieces = [];
  for (let i = 0; i < n; i++) if (start[i] !== 'X') pieces.push(i);
  const result = new Array(n).fill('X');
  let prev = -1;
  for (let t = 0; t < pieces.length; t++) {
    const from = pieces[t], ch = start[from];
    const limit = t + 1 < pieces.length ? pieces[t + 1] - 1 : n - 1;
    const pos = ch === 'L' ? int(prev + 1, from) : int(Math.max(prev + 1, from), limit);
    result[pos] = ch;
    prev = pos;
  }
  if (mode >= 0.65) {
    // Spoil it a little, which usually makes it unreachable.
    const k = int(0, n - 1);
    if (rand() < 0.5 || n < 2) result[k] = 'LRX'[int(0, 2)];
    else { const a = Math.min(k, n - 2); [result[a], result[a + 1]] = [result[a + 1], result[a]]; }
  }
  return [start.join(''), result.join('')];
}
